var msgTemp = { payload: Number(msg.req.params.temp) };
var msgHum = { payload: Number(msg.req.params.hum) };
return [msgTemp, msgHum];

try {
    const saved = JSON.parse(msg.payload);
    let state = flow.get('plantState');
    if (state && saved && typeof saved.volumeL === 'number') {
        state.volumeL = saved.volumeL;
        state.levelPct = saved.levelPct;
        state.targetLevelPct = saved.targetLevelPct || 65;
        state.primaryPump = saved.primaryPump || 'P1';
        state.mode = saved.mode || 'AUTO';
        state.kpis = saved.kpis || state.kpis;
        state.alarmHistory = saved.alarmHistory || [];
        flow.set('plantState', state);
        node.status({fill: 'green', shape: 'dot', text: 'Estado restaurado de disco'});
    }
} catch (e) {
    node.status({fill: 'yellow', shape: 'ring', text: 'Sin archivo previo, usando defaults'});
}
return null;

// ============================================================================
// CONFIGURACIÓN CENTRALIZADA (Fácil adaptación ante cambios de requerimientos)
// ============================================================================
const CONFIG = {
    deviceId: 'UTMACH-A02-PUMP-STATION-01',
    dtSeconds: 1.0,
    tank: {
        maxVolumeL: 2000.0,       // Parámetro de referencia: 2000 L
        initialLevelPct: 55.0,    // Inicia en 55% para observar llenado hacia 65%
        defaultTargetPct: 65.0,   // Nivel objetivo de referencia: 65%
        minSafeTargetPct: 15.0,
        maxSafeTargetPct: 95.0
    },
    pumps: {
        P1: { id: 'P1', nominalFlowLmin: 80.0, idlePowerKw: 0.35, nominalPressureBar: 2.15 },
        P2: { id: 'P2', nominalFlowLmin: 80.0, idlePowerKw: 0.35, nominalPressureBar: 2.15 },
        parallelLossFactor: 0.94, // Factor hidráulico cuando operan 2 bombas en paralelo
        electroMechEfficiency: 0.72
    },
    control: {
        hysteresisLow1Pct: 1.5,   // Activa bomba principal si nivel < target - 1.5%
        hysteresisLow2Pct: 8.0,   // Activa bomba apoyo si nivel < target - 8.0%
        hysteresisHigh1Pct: 1.0,  // Apaga bomba apoyo si nivel >= target + 1.0%
        hysteresisHigh2Pct: 2.0   // Apaga bomba principal si nivel >= target + 2.0%
    },
    alarms: {
        lowLevelThresholdPct: 20.0,
        overpressureThresholdBar: 4.5,
        dryRunCriticalLevelPct: 8.0
    },
    topics: {
        telemetry: 'utm/iot/A02/telemetry',
        status: 'utm/iot/A02/status',
        commands: 'utm/iot/A02/commands',
        alarms: 'utm/iot/A02/alarms',
        ack: 'utm/iot/A02/ack'
    }
};

const initialVolumeL = (CONFIG.tank.initialLevelPct / 100.0) * CONFIG.tank.maxVolumeL;

const plantState = {
    initializedAt: new Date().toISOString(),
    totalSimSeconds: 0,
    activePumpSeconds: 0,
    mode: 'AUTO',                 // 'AUTO' | 'MANUAL'
    targetLevelPct: CONFIG.tank.defaultTargetPct,
    primaryPump: 'P1',            // 'P1' | 'P2'
    volumeL: initialVolumeL,
    levelPct: CONFIG.tank.initialLevelPct,
    inflowLmin: 0.0,
    outflowLmin: 40.0,
    netFlowLmin: 0.0,
    pressureBar: 0.22,
    powerKw: 0.0,
    safetyInterlockActive: false,
    interlockReason: 'NONE',
    pumps: {
        P1: { active: true, fault: false, efficiency: 1.0, currentFlowLmin: 0.0 },
        P2: { active: false, fault: false, efficiency: 1.0, currentFlowLmin: 0.0 }
    },
    disturbances: {
        baseDemandLmin: 40.0,     // Consumo normal inicial (40 L/min)
        leakFlowLmin: 0.0,        // Fuga en tanque/tubería (0 L/min en operación normal)
        suctionAvailable: true,   // Cisterna de succión con agua disponible
        dischargeRestriction: 1.0 // 1.0 = normal, > 1.8 = obstrucción / sobrepresión
    },
    kpis: {
        pumpedVolumeM3: 0.0,
        estimatedEnergyKwh: 0.0,
        activeTimePct: 0.0,
        levelErrorPct: Math.abs(CONFIG.tank.defaultTargetPct - CONFIG.tank.initialLevelPct),
        volumetricEfficiencyPct: 100.0
    },
    activeAlarms: {},
    alarmHistory: [],
    processedMsgIds: []
};

flow.set('CONFIG', CONFIG);
flow.set('plantState', plantState);
node.status({fill: 'green', shape: 'dot', text: 'Planta A02 inicializada'});
return null;

const CONFIG = flow.get('CONFIG');
let s = flow.get('plantState');
if (!CONFIG || !s) return null;

const dt = CONFIG.dtSeconds;
const nowIso = new Date().toISOString();
s.totalSimSeconds += dt;

// 1. EVALUACIÓN DE ALARMAS Y BLOQUEOS DE SEGURIDAD (INTERLOCKS)
const anyPumpTryingToRun = s.pumps.P1.active || s.pumps.P2.active;
const isDryRunCondition = (!s.disturbances.suctionAvailable) || (s.levelPct < CONFIG.alarms.dryRunCriticalLevelPct && !s.disturbances.suctionAvailable);

// Helper para gestionar disparo/despeje de alarmas
function updateAlarm(code, name, conditionText, severity, isTriggered, currentValueStr) {
    if (isTriggered) {
        if (!s.activeAlarms[code]) {
            const alarmObj = {
                id: 'alm-' + Date.now() + '-' + code,
                code: code,
                name: name,
                condition: conditionText,
                severity: severity,
                triggeredAt: nowIso,
                currentValue: currentValueStr,
                acknowledged: false,
                acknowledgedAt: null
            };
            s.activeAlarms[code] = alarmObj;
            s.alarmHistory.unshift(Object.assign({ event: 'TRIGGERED' }, alarmObj));
            if (s.alarmHistory.length > 50) s.alarmHistory.pop();
            return true;
        } else {
            s.activeAlarms[code].currentValue = currentValueStr;
        }
    } else {
        if (s.activeAlarms[code]) {
            const cleared = Object.assign({}, s.activeAlarms[code], {
                event: 'CLEARED',
                clearedAt: nowIso
            });
            s.alarmHistory.unshift(cleared);
            if (s.alarmHistory.length > 50) s.alarmHistory.pop();
            delete s.activeAlarms[code];
            return true;
        }
    }
    return false;
}

// 2. LÓGICA DE CONTROL AUTOMÁTICO (Si no hay bloqueo activo)
const secondaryPump = (s.primaryPump === 'P1') ? 'P2' : 'P1';
const primaryObj = s.pumps[s.primaryPump];
const secondaryObj = s.pumps[secondaryPump];

if (s.mode === 'AUTO' && !s.safetyInterlockActive) {
    const err = s.targetLevelPct - s.levelPct; // positivo si falta llenar
    // Bomba principal
    if (!primaryObj.fault) {
        if (err >= CONFIG.control.hysteresisLow1Pct) primaryObj.active = true;
        else if (err <= -CONFIG.control.hysteresisHigh2Pct) primaryObj.active = false;
    } else {
        primaryObj.active = false;
    }
    // Bomba secundaria (apoyo por alta demanda o por falla de la principal)
    if (!secondaryObj.fault) {
        if (primaryObj.fault && err >= CONFIG.control.hysteresisLow1Pct) {
            secondaryObj.active = true; // Relevo automático por falla
        } else if (err >= CONFIG.control.hysteresisLow2Pct || s.levelPct < CONFIG.alarms.lowLevelThresholdPct) {
            secondaryObj.active = true; // Refuerzo en paralelo
        } else if (err <= -CONFIG.control.hysteresisHigh1Pct) {
            secondaryObj.active = false;
        }
    } else {
        secondaryObj.active = false;
    }
}

// Corte por nivel máximo (99.5%) para evitar rebose
if (s.levelPct >= 99.5) {
    s.pumps.P1.active = false;
    s.pumps.P2.active = false;
}

// 3. CÁLCULO DE CAUDALES (Balance de Masa)
const activeCount = (s.pumps.P1.active ? 1 : 0) + (s.pumps.P2.active ? 1 : 0);
const parallelFactor = (activeCount === 2) ? CONFIG.pumps.parallelLossFactor : 1.0;
const suctionFactor = s.disturbances.suctionAvailable ? 1.0 : 0.05;

// Ruido hidrodinámico acotado
const noiseP1 = s.pumps.P1.active ? (Math.random() - 0.5) * 1.2 : 0.0;
const noiseP2 = s.pumps.P2.active ? (Math.random() - 0.5) * 1.2 : 0.0;

s.pumps.P1.currentFlowLmin = s.pumps.P1.active && !s.pumps.P1.fault
    ? Math.max(0, CONFIG.pumps.P1.nominalFlowLmin * s.pumps.P1.efficiency * parallelFactor * suctionFactor + noiseP1)
    : 0.0;

s.pumps.P2.currentFlowLmin = s.pumps.P2.active && !s.pumps.P2.fault
    ? Math.max(0, CONFIG.pumps.P2.nominalFlowLmin * s.pumps.P2.efficiency * parallelFactor * suctionFactor + noiseP2)
    : 0.0;

s.inflowLmin = s.pumps.P1.currentFlowLmin + s.pumps.P2.currentFlowLmin;

const demandNoise = (s.disturbances.baseDemandLmin > 0) ? (Math.random() - 0.5) * 1.6 : 0.0;
const effectiveDemand = (s.volumeL > 0) ? Math.max(0, s.disturbances.baseDemandLmin + demandNoise) : 0.0;
const effectiveLeak = (s.volumeL > 0) ? Math.max(0, s.disturbances.leakFlowLmin) : 0.0;
s.outflowLmin = effectiveDemand + effectiveLeak;
s.netFlowLmin = s.inflowLmin - s.outflowLmin;

// Evolución del volumen y nivel en función de dt y del estado anterior
const deltaVolumeL = s.netFlowLmin * (dt / 60.0);
s.volumeL = Math.min(CONFIG.tank.maxVolumeL, Math.max(0.0, s.volumeL + deltaVolumeL));
s.levelPct = (s.volumeL / CONFIG.tank.maxVolumeL) * 100.0;

// 4. CÁLCULO DE PRESIÓN (bar) Y POTENCIA ELÉCTRICA (kW)
const hydrostaticBar = 0.40 * (s.levelPct / 100.0);
const pump1Head = (s.pumps.P1.active && !s.pumps.P1.fault) ? CONFIG.pumps.P1.nominalPressureBar * s.pumps.P1.efficiency * suctionFactor : 0.0;
const pump2Head = (s.pumps.P2.active && !s.pumps.P2.fault) ? CONFIG.pumps.P2.nominalPressureBar * s.pumps.P2.efficiency * suctionFactor : 0.0;
const combinedPumpBar = (pump1Head + pump2Head) * (activeCount === 2 ? 0.88 : 1.0) * s.disturbances.dischargeRestriction;
const pressureDropOutflow = 0.0035 * s.outflowLmin;
const pressureNoise = (Math.random() - 0.5) * 0.04;

s.pressureBar = Math.max(0.0, hydrostaticBar + combinedPumpBar - pressureDropOutflow + pressureNoise);

// Potencia eléctrica P = P_vacio + (Q * P_bar) / (600 * eta)
let powerP1 = 0.0;
if (s.pumps.P1.active) {
    powerP1 = CONFIG.pumps.P1.idlePowerKw + (s.pumps.P1.currentFlowLmin * s.pressureBar) / (600.0 * CONFIG.pumps.electroMechEfficiency);
}
let powerP2 = 0.0;
if (s.pumps.P2.active) {
    powerP2 = CONFIG.pumps.P2.idlePowerKw + (s.pumps.P2.currentFlowLmin * s.pressureBar) / (600.0 * CONFIG.pumps.electroMechEfficiency);
}
s.powerKw = Math.max(0.0, powerP1 + powerP2);

// 5. EVALUACIÓN DE LAS 3 ALARMAS OBLIGATORIAS Y BLOQUEO POR ESTADO INSEGURO
const lowLevelTriggered = s.levelPct < CONFIG.alarms.lowLevelThresholdPct;
const overpressureTriggered = s.pressureBar > CONFIG.alarms.overpressureThresholdBar;
const dryRunTriggered = (!s.disturbances.suctionAvailable && (s.pumps.P1.active || s.pumps.P2.active || s.safetyInterlockActive)) || (s.levelPct < CONFIG.alarms.dryRunCriticalLevelPct && s.outflowLmin > s.inflowLmin && !s.disturbances.suctionAvailable);

let alarmsChanged = false;
alarmsChanged = updateAlarm('LOW_LEVEL', 'Nivel Bajo en Tanque', 'Nivel < ' + CONFIG.alarms.lowLevelThresholdPct + ' %', 'HIGH', lowLevelTriggered, s.levelPct.toFixed(1) + ' %') || alarmsChanged;
alarmsChanged = updateAlarm('OVERPRESSURE', 'Sobrepresión en Línea', 'Presión > ' + CONFIG.alarms.overpressureThresholdBar + ' bar', 'CRITICAL', overpressureTriggered, s.pressureBar.toFixed(2) + ' bar') || alarmsChanged;
alarmsChanged = updateAlarm('DRY_RUN', 'Funcionamiento en Seco', 'Sin suministro en succión con demanda de bombeo', 'CRITICAL', dryRunTriggered, 'Succión: ' + (s.disturbances.suctionAvailable ? 'OK' : 'SECA')) || alarmsChanged;

// Aplicación de Bloqueo por Estado Inseguro (Interlock)
if (overpressureTriggered || dryRunTriggered) {
    s.safetyInterlockActive = true;
    s.interlockReason = dryRunTriggered ? 'PROTECCIÓN POR FUNCIONAMIENTO EN SECO' : 'PROTECCIÓN POR SOBREPRESIÓN (> 4.5 bar)';
    s.pumps.P1.active = false;
    s.pumps.P2.active = false;
} else {
    s.safetyInterlockActive = false;
    s.interlockReason = 'NONE';
}

// 6. CÁLCULO DE LOS 5 KPIs OBLIGATORIOS
if (s.pumps.P1.active || s.pumps.P2.active) {
    s.activePumpSeconds += dt;
}
// 1. Volumen bombeado (m³): conversión de L a m³
s.kpis.pumpedVolumeM3 += (s.inflowLmin * (dt / 60.0)) / 1000.0;
// 2. Energía estimada (kWh): kW * (dt / 3600)
s.kpis.estimatedEnergyKwh += s.powerKw * (dt / 3600.0);
// 3. Tiempo activo (%)
s.kpis.activeTimePct = (s.activePumpSeconds / Math.max(1, s.totalSimSeconds)) * 100.0;
// 4. Error de nivel (%)
s.kpis.levelErrorPct = Math.abs(s.targetLevelPct - s.levelPct);
// 5. Eficiencia volumétrica (%)
const theoreticalFlow = activeCount * CONFIG.pumps.P1.nominalFlowLmin;
if (theoreticalFlow > 0) {
    const netDelivered = Math.max(0, s.inflowLmin - s.disturbances.leakFlowLmin);
    s.kpis.volumetricEfficiencyPct = Math.min(100.0, Math.max(0.0, (netDelivered / theoreticalFlow) * 100.0));
} else {
    const avgPumpEff = ((s.pumps.P1.fault ? 0 : s.pumps.P1.efficiency) + (s.pumps.P2.fault ? 0 : s.pumps.P2.efficiency)) / 2.0;
    const leakPenalty = s.disturbances.leakFlowLmin > 0 ? Math.max(0, 1 - s.disturbances.leakFlowLmin / 80.0) : 1.0;
    s.kpis.volumetricEfficiencyPct = avgPumpEff * leakPenalty * 100.0;
}

flow.set('plantState', s);

// Construcción de mensajes de salida
const telemetryMsg = {
    topic: CONFIG.topics.telemetry,
    payload: {
        deviceId: CONFIG.deviceId,
        timestamp: nowIso,
        variables: {
            level: { value: Number(s.levelPct.toFixed(2)), unit: '%', volumeL: Number(s.volumeL.toFixed(1)) },
            flow: {
                value: Number(s.inflowLmin.toFixed(2)),
                unit: 'L/min',
                inflowLmin: Number(s.inflowLmin.toFixed(2)),
                outflowLmin: Number(s.outflowLmin.toFixed(2)),
                leakLmin: Number(s.disturbances.leakFlowLmin.toFixed(2))
            },
            pressure: { value: Number(s.pressureBar.toFixed(2)), unit: 'bar' },
            power: { value: Number(s.powerKw.toFixed(2)), unit: 'kW' }
        },
        kpis: {
            pumpedVolumeM3: { value: Number(s.kpis.pumpedVolumeM3.toFixed(4)), unit: 'm³' },
            estimatedEnergyKwh: { value: Number(s.kpis.estimatedEnergyKwh.toFixed(4)), unit: 'kWh' },
            activeTimePct: { value: Number(s.kpis.activeTimePct.toFixed(1)), unit: '%' },
            levelErrorPct: { value: Number(s.kpis.levelErrorPct.toFixed(2)), unit: '%' },
            volumetricEfficiencyPct: { value: Number(s.kpis.volumetricEfficiencyPct.toFixed(1)), unit: '%' }
        }
    }
};

const statusMsg = {
    topic: CONFIG.topics.status,
    payload: {
        deviceId: CONFIG.deviceId,
        timestamp: nowIso,
        mode: s.mode,
        targetLevelPct: s.targetLevelPct,
        primaryPump: s.primaryPump,
        safetyInterlockActive: s.safetyInterlockActive,
        interlockReason: s.interlockReason,
        pumps: {
            P1: {
                active: s.pumps.P1.active,
                fault: s.pumps.P1.fault,
                efficiency: s.pumps.P1.efficiency,
                flowLmin: Number(s.pumps.P1.currentFlowLmin.toFixed(1))
            },
            P2: {
                active: s.pumps.P2.active,
                fault: s.pumps.P2.fault,
                efficiency: s.pumps.P2.efficiency,
                flowLmin: Number(s.pumps.P2.currentFlowLmin.toFixed(1))
            }
        },
        disturbances: s.disturbances
    }
};

const alarmsMsg = {
    topic: CONFIG.topics.alarms,
    payload: {
        deviceId: CONFIG.deviceId,
        timestamp: nowIso,
        activeAlarms: Object.values(s.activeAlarms),
        history: s.alarmHistory.slice(0, 20)
    }
};

let persistMsg = null;
if (Math.round(s.totalSimSeconds) % 5 === 0) {
    persistMsg = {
        payload: JSON.stringify({
            volumeL: s.volumeL,
            levelPct: s.levelPct,
            targetLevelPct: s.targetLevelPct,
            primaryPump: s.primaryPump,
            mode: s.mode,
            kpis: s.kpis,
            alarmHistory: s.alarmHistory
        }, null, 2)
    };
}

node.status({
    fill: s.safetyInterlockActive ? 'red' : 'green',
    shape: 'dot',
    text: `Nivel: ${s.levelPct.toFixed(1)}% | Q_in: ${s.inflowLmin.toFixed(0)} L/m | P: ${s.pressureBar.toFixed(2)} bar`
});

return [telemetryMsg, statusMsg, alarmsMsg, persistMsg];

const CONFIG = flow.get('CONFIG');
let s = flow.get('plantState');
if (!CONFIG || !s) return null;

const cmd = (typeof msg.payload === 'string') ? JSON.parse(msg.payload) : msg.payload;
const nowIso = new Date().toISOString();
const msgId = cmd.msgId || ('cmd-' + Date.now());

// 1. PREVENCIÓN DE COMANDOS DUPLICADOS (Idempotencia)
if (s.processedMsgIds.includes(msgId)) {
    const dupAck = {
        topic: CONFIG.topics.ack,
        payload: {
            ackId: 'ack-' + Date.now(),
            msgId: msgId,
            deviceId: CONFIG.deviceId,
            timestamp: nowIso,
            action: cmd.action || 'UNKNOWN',
            status: 'IGNORED_DUPLICATE',
            message: 'Comando duplicado detectado y descartado por idempotencia.'
        }
    };
    return [dupAck, null, null];
}
s.processedMsgIds.push(msgId);
if (s.processedMsgIds.length > 100) s.processedMsgIds.shift();

let ackStatus = 'EXECUTED';
let ackMessage = 'Maniobra ejecutada correctamente.';
const action = cmd.action;
const p = cmd.params || {};

// 2. PROCESAMIENTO DE LAS 3 ACCIONES DE CONTROL Y ESCENARIOS DE INGENIERÍA
switch (action) {
    case 'SET_PUMP_STATE': {
        const pumpId = p.pumpId; // 'P1' o 'P2'
        const targetActive = Boolean(p.active);
        if (!s.pumps[pumpId]) {
            ackStatus = 'REJECTED_INVALID_PARAM';
            ackMessage = 'Identificador de bomba inválido.';
        } else if (targetActive && s.safetyInterlockActive) {
            ackStatus = 'REJECTED_UNSAFE_STATE';
            ackMessage = `Bloqueo por estado inseguro activo: ${s.interlockReason}. No se puede encender ${pumpId}.`;
        } else if (targetActive && s.pumps[pumpId].fault) {
            ackStatus = 'REJECTED_UNSAFE_STATE';
            ackMessage = `Bloqueo: La bomba ${pumpId} se encuentra averiada (falla electromecánica).`;
        } else if (targetActive && s.levelPct >= 99.0) {
            ackStatus = 'REJECTED_UNSAFE_STATE';
            ackMessage = 'Bloqueo por seguridad: Tanque lleno (>= 99%).';
        } else {
            // Al operar manualmente una bomba, pasa a modo MANUAL o respeta el modo indicado
            if (p.forceManual !== false) s.mode = 'MANUAL';
            s.pumps[pumpId].active = targetActive;
            ackMessage = `Bomba ${pumpId} ${targetActive ? 'ACTIVADA' : 'DESACTIVADA'} en modo ${s.mode}.`;
        }
        break;
    }
    case 'SET_TARGET_LEVEL': {
        const newTarget = Number(p.targetLevelPct);
        if (isNaN(newTarget) || newTarget < CONFIG.tank.minSafeTargetPct || newTarget > CONFIG.tank.maxSafeTargetPct) {
            ackStatus = 'REJECTED_UNSAFE_STATE';
            ackMessage = `Consigna fuera de rango seguro (${CONFIG.tank.minSafeTargetPct}% - ${CONFIG.tank.maxSafeTargetPct}%).`;
        } else {
            s.targetLevelPct = newTarget;
            ackMessage = `Nivel objetivo actualizado a ${newTarget.toFixed(1)} %.`;
        }
        break;
    }
    case 'TOGGLE_PRIMARY_PUMP': {
        const requestedPrimary = p.primaryPump || (s.primaryPump === 'P1' ? 'P2' : 'P1');
        if (s.pumps[requestedPrimary] && s.pumps[requestedPrimary].fault) {
            ackStatus = 'REJECTED_UNSAFE_STATE';
            ackMessage = `No se puede asignar ${requestedPrimary} como principal porque está en estado de falla.`;
        } else {
            s.primaryPump = (requestedPrimary === 'P2') ? 'P2' : 'P1';
            ackMessage = `Bomba principal conmutada a ${s.primaryPump}.`;
        }
        break;
    }
    case 'SET_CONTROL_MODE': {
        s.mode = (p.mode === 'MANUAL') ? 'MANUAL' : 'AUTO';
        ackMessage = `Modo de control cambiado a ${s.mode}.`;
        break;
    }
    case 'ACK_ALARM': {
        const code = p.alarmCode;
        if (code === 'ALL') {
            Object.values(s.activeAlarms).forEach(a => {
                a.acknowledged = true;
                a.acknowledgedAt = nowIso;
            });
            ackMessage = 'Todas las alarmas activas han sido reconocidas por el operador.';
        } else if (s.activeAlarms[code]) {
            s.activeAlarms[code].acknowledged = true;
            s.activeAlarms[code].acknowledgedAt = nowIso;
            ackMessage = `Alarma ${code} reconocida exitosamente.`;
        } else {
            ackStatus = 'IGNORED_NOT_ACTIVE';
            ackMessage = `La alarma ${code} ya no se encuentra activa.`;
        }
        break;
    }
    case 'INJECT_SCENARIO': {
        const sc = p.scenario;
        if (sc === 'NORMAL_FILL') {
            s.mode = 'AUTO';
            s.targetLevelPct = 65.0;
            s.pumps.P1.fault = false; s.pumps.P1.efficiency = 1.0;
            s.pumps.P2.fault = false; s.pumps.P2.efficiency = 1.0;
            s.disturbances.baseDemandLmin = 40.0;
            s.disturbances.leakFlowLmin = 0.0;
            s.disturbances.suctionAvailable = true;
            s.disturbances.dischargeRestriction = 1.0;
            ackMessage = 'Prueba 1 activada: Llenado y operación normal (Demanda = 40 L/min, Consigna = 65%).';
        } else if (sc === 'HIGH_CONSUMPTION') {
            s.mode = 'AUTO';
            s.disturbances.baseDemandLmin = 125.0;
            ackMessage = 'Prueba 2 activada: Aumento severo de consumo a 125 L/min (requiere entrada de bomba secundaria).';
        } else if (sc === 'LEAK_FAULT') {
            s.disturbances.leakFlowLmin = 55.0;
            ackMessage = 'Prueba 3 activada: Fuga crítica de 55 L/min en tubería/tanque (caída de eficiencia volumétrica y nivel).';
        } else if (sc === 'PUMP_FAULT') {
            const targetFaultPump = s.primaryPump;
            s.pumps[targetFaultPump].fault = true;
            s.pumps[targetFaultPump].active = false;
            s.pumps[targetFaultPump].efficiency = 0.0;
            ackMessage = `Prueba 4 activada: Avería electromecánica en bomba principal (${targetFaultPump}). Conmutando a respaldo.`;
        } else if (sc === 'DRY_RUN_FAULT') {
            s.disturbances.suctionAvailable = false;
            ackMessage = 'Falla inyectada: Pérdida de suministro en cisterna de succión (Disparo de Funcionamiento en Seco).';
        } else if (sc === 'OVERPRESSURE_FAULT') {
            s.disturbances.dischargeRestriction = 2.4;
            ackMessage = 'Falla inyectada: Obstrucción en colector de descarga (Disparo de Sobrepresión > 4.5 bar).';
        } else if (sc === 'RECOVERY') {
            s.mode = 'AUTO';
            s.pumps.P1.fault = false; s.pumps.P1.efficiency = 1.0;
            s.pumps.P2.fault = false; s.pumps.P2.efficiency = 1.0;
            s.disturbances.baseDemandLmin = 40.0;
            s.disturbances.leakFlowLmin = 0.0;
            s.disturbances.suctionAvailable = true;
            s.disturbances.dischargeRestriction = 1.0;
            s.safetyInterlockActive = false;
            s.interlockReason = 'NONE';
            ackMessage = 'Prueba 5 activada: Recuperación integral del sistema, despeje de fallas y retorno a consigna.';
        } else if (sc === 'CUSTOM_DISTURBANCE') {
            if (typeof p.baseDemandLmin === 'number') s.disturbances.baseDemandLmin = Math.max(0, p.baseDemandLmin);
            if (typeof p.leakFlowLmin === 'number') s.disturbances.leakFlowLmin = Math.max(0, p.leakFlowLmin);
            if (typeof p.suctionAvailable === 'boolean') s.disturbances.suctionAvailable = p.suctionAvailable;
            if (typeof p.dischargeRestriction === 'number') s.disturbances.dischargeRestriction = Math.max(0.5, p.dischargeRestriction);
            ackMessage = 'Parámetros de ingeniería actualizados en el simulador.';
        }
        break;
    }
    default:
        ackStatus = 'REJECTED_UNKNOWN_COMMAND';
        ackMessage = `Acción desconocida: ${action}`;
}

flow.set('plantState', s);

const ackMsg = {
    topic: CONFIG.topics.ack,
    payload: {
        ackId: 'ack-' + Date.now(),
        msgId: msgId,
        deviceId: CONFIG.deviceId,
        timestamp: nowIso,
        action: action,
        status: ackStatus,
        message: ackMessage
    }
};

const statusMsg = {
    topic: CONFIG.topics.status,
    payload: {
        deviceId: CONFIG.deviceId,
        timestamp: nowIso,
        mode: s.mode,
        targetLevelPct: s.targetLevelPct,
        primaryPump: s.primaryPump,
        safetyInterlockActive: s.safetyInterlockActive,
        interlockReason: s.interlockReason,
        pumps: {
            P1: { active: s.pumps.P1.active, fault: s.pumps.P1.fault, efficiency: s.pumps.P1.efficiency, flowLmin: s.pumps.P1.currentFlowLmin },
            P2: { active: s.pumps.P2.active, fault: s.pumps.P2.fault, efficiency: s.pumps.P2.efficiency, flowLmin: s.pumps.P2.currentFlowLmin }
        },
        disturbances: s.disturbances
    }
};

const alarmsMsg = {
    topic: CONFIG.topics.alarms,
    payload: {
        deviceId: CONFIG.deviceId,
        timestamp: nowIso,
        activeAlarms: Object.values(s.activeAlarms),
        history: s.alarmHistory.slice(0, 20)
    }
};

return [ackMsg, statusMsg, alarmsMsg];

// Este flujo NO accede a ninguna variable del simulador; solo procesa lo recibido por MQTT.
let buffer = flow.get('telemetryBuffer') || [];
let lastStatus = flow.get('lastStatus') || null;
let lastAlarms = flow.get('lastAlarms') || null;
let ackLog = flow.get('ackLog') || [];

const topic = msg.topic;
const data = msg.payload;

if (topic === 'utm/iot/A02/telemetry') {
    buffer.push(data);
    // Guardar hasta 600 muestras (10 minutos a 1s) para soportar ventana temporal configurable
    if (buffer.length > 600) buffer.shift();
    flow.set('telemetryBuffer', buffer);
} else if (topic === 'utm/iot/A02/status') {
    lastStatus = data;
    flow.set('lastStatus', lastStatus);
} else if (topic === 'utm/iot/A02/alarms') {
    lastAlarms = data;
    flow.set('lastAlarms', lastAlarms);
} else if (topic === 'utm/iot/A02/ack') {
    ackLog.unshift(data);
    if (ackLog.length > 30) ackLog.pop();
    flow.set('ackLog', ackLog);
}

const wsMsg = {
    payload: JSON.stringify({
        type: 'MQTT_PACKET',
        topic: topic,
        data: data
    })
};

return [wsMsg];

let parsed;
try {
    parsed = (typeof msg.payload === 'string') ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    return null;
}

// Si el navegador acaba de conectarse o reconectarse, enviamos el buffer histórico y el último estado retenido
if (parsed.type === 'REQUEST_SYNC') {
    const syncPayload = {
        type: 'INITIAL_SYNC',
        history: flow.get('telemetryBuffer') || [],
        lastStatus: flow.get('lastStatus') || null,
        lastAlarms: flow.get('lastAlarms') || null,
        ackLog: flow.get('ackLog') || []
    };
    return [null, { payload: JSON.stringify(syncPayload) }];
}

// Si el navegador envía un comando, lo publicamos en utm/iot/A02/commands por MQTT
if (parsed.type === 'PUBLISH_COMMAND') {
    const mqttMsg = {
        topic: 'utm/iot/A02/commands',
        payload: parsed.command
    };
    return [mqttMsg, null];
}

return null;
